ROOT=Path(__file__).resolve().parent

import csv

def read_tv4_csv(filename):
    path = ROOT / 'tv4_results' / filename
    if not path.exists():
        return []
    with path.open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))

REQUIRED_RESULTS = ['rq1_rq2_summary.csv','rq3_summary.csv','rq4_summary.csv','ml_summary_valid.csv']
