@st.fragment(run_every="60s")
def render_dashboard():
    news, errors, checked = load_news()
    if st.button("↻ Refresh live news", key="live_refresh", help="Fetch latest RSS articles without changing historical research data"):
        load_news.clear()
        news, errors, checked = load_news()
    # Replace only the four hard-coded example headlines inside the existing News Sentiment card.
    html_live = re.sub(r'<div class="newshead">Latest News.*?</section></div><div class="gridbottom">',
                       lambda m: make_news_markup(news, checked, errors) + '</section></div><div class="gridbottom">',
                       html, count=1, flags=re.S)
    # Greeting uses Vietnam time; refreshes with the existing Streamlit fragment.
    from datetime import datetime
    from zoneinfo import ZoneInfo
    hour_vn = datetime.now(ZoneInfo("Asia/Ho_Chi_Minh")).hour
    greeting = ("GOOD MORNING" if 5 <= hour_vn < 12 else
                "GOOD AFTERNOON" if 12 <= hour_vn < 18 else "GOOD EVENING")
    html_live = html_live.replace(
        '<span class="greeting-badge">GOOD EVENING</span>',
        '<span class="greeting-badge">' + greeting + '</span>', 1
    )
    components.html(html_live, height=1180, scrolling=True)
render_dashboard()
